// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address internal deployer = address(0x1234);

    function setUp() public {
        vm.prank(deployer);
        c = new SimpleWallet();
        vm.deal(deployer, 100 ether);
        vm.prank(deployer);
        (bool ok,) = address(c).call{value: 100 ether}("");
        require(ok);
    }

    function testFuzz_property(address target, uint256 value, bytes calldata data, address caller) public {
        vm.assume(caller != deployer);
        vm.assume(caller != address(c));
        vm.assume(target != address(c));
        value = bound(value, 0, 100 ether);
        uint256 balanceBefore = address(c).balance;

        vm.deal(caller, value);
        vm.prank(caller);
        bool didNotRevert;
        try c.sendMoney(target, value, data) {
            didNotRevert = true;
        } catch {
            didNotRevert = false;
        }

        uint256 balanceAfter = address(c).balance;
        assertTrue(didNotRevert ? balanceAfter >= balanceBefore : balanceAfter == balanceBefore);
    }
}
